type GameBoyColorId = 'black' | 'yellow' | 'red' | 'green' | 'blue' | 'pearl' | 'silver' | 'gray';

type GameBoyColor = {
  id: GameBoyColorId;
  name: string;
  texture: string;
  swatch: string;
  shortcut: string;
};

// Eight reference colourways baked from the SAME `baked-game-boy.jpg` atlas
// (see apps/game-boy/tools/generate-game-boy-shell-textures.mjs). Order here
// is the display order in the picker (2x4 grid) and the 1-8 keyboard
// shortcut order. The classic gray DMG is first and is the default shell
// colour; the black Play It Loud edition remains available on shortcut 2.
const GAME_BOY_COLORS: GameBoyColor[] = [
  { id: 'gray', name: 'Original', texture: 'baked-game-boy.jpg', swatch: '#c7c5c8', shortcut: '1' },
  { id: 'black', name: 'Black', texture: 'baked-game-boy-black.jpg', swatch: '#26262a', shortcut: '2' },
  { id: 'yellow', name: 'Yellow', texture: 'baked-game-boy-yellow.jpg', swatch: '#e8b93a', shortcut: '3' },
  { id: 'red', name: 'Red', texture: 'baked-game-boy-red.jpg', swatch: '#9c2b34', shortcut: '4' },
  { id: 'green', name: 'Green', texture: 'baked-game-boy-green.jpg', swatch: '#3f8a5b', shortcut: '5' },
  { id: 'blue', name: 'Blue', texture: 'baked-game-boy-blue.jpg', swatch: '#3f6fa8', shortcut: '6' },
  { id: 'pearl', name: 'Pearl', texture: 'baked-game-boy-pearl.jpg', swatch: '#e8e0d0', shortcut: '7' },
  { id: 'silver', name: 'Silver', texture: 'baked-game-boy-silver.jpg', swatch: '#b7bac0', shortcut: '8' },
];

const DEFAULT_GAME_BOY_COLOR: GameBoyColorId = 'gray';

function getGameBoyShellColor(colorId: GameBoyColorId): GameBoyColor {
  return GAME_BOY_COLORS.find((color: GameBoyColor) => color.id === colorId) ?? GAME_BOY_COLORS[0];
}

export {
  GAME_BOY_COLORS,
  DEFAULT_GAME_BOY_COLOR,
  getGameBoyShellColor,
};
export type { GameBoyColor, GameBoyColorId };
