import { EventEmitter } from 'pixi.js';
import type { UserRomSource } from '../scene/game-boy-scene/game-boy-games/games/emulator/user-rom-source';

// A self-contained DOM overlay (no framework) mirroring the GameBoyColorPicker
// pattern: builds its own markup, reads shared styles from style.css. Lets the
// player run a ROM file they picked from their own device — the app ships none.

const MAX_ROM_BYTES = 8 * 1024 * 1024;
const MIN_ROM_BYTES = 1024;
const MAX_TITLE_CHARS = 18;

function readLanguage(): 'en' | 'zh' {
  try {
    return new URLSearchParams(window.location.search).get('lang') === 'zh' ? 'zh' : 'en';
  } catch {
    return 'en';
  }
}

const COPY = {
  en: {
    button: 'LOAD ROM',
    hint: 'Play a .gb / .gbc file from your device',
    invalid: 'That file is not a Game Boy ROM (.gb / .gbc).',
    tooLarge: 'That file is too large for a Game Boy ROM.',
    tooSmall: 'That file is too small to be a Game Boy ROM.',
  },
  zh: {
    button: '加载 ROM',
    hint: '运行自己设备里的 .gb / .gbc 文件',
    invalid: '这不是 Game Boy ROM 文件（.gb / .gbc）。',
    tooLarge: '文件太大，不是有效的 Game Boy ROM。',
    tooSmall: '文件太小，不是有效的 Game Boy ROM。',
  },
} as const;

export default class GameBoyRomLoader {
  public events: EventEmitter;

  private root: HTMLDivElement;
  private input: HTMLInputElement;
  private status: HTMLParagraphElement;
  private statusTimer: number | null;

  constructor() {
    this.events = new EventEmitter();
    this.statusTimer = null;

    this.build();
    this.initSignals();
  }

  private build(): void {
    const copy = COPY[readLanguage()];

    const root = this.root = document.createElement('div');
    root.className = 'gbx-rom-loader';

    root.innerHTML = `
      <button
        class="gbx-rom-loader__button"
        type="button"
        data-rom-action="pick"
        title="${copy.hint}"
      >${copy.button}</button>
      <input
        class="gbx-rom-loader__input"
        type="file"
        accept=".gb,.gbc"
        tabindex="-1"
        aria-hidden="true"
      />
      <p class="gbx-rom-loader__status" role="status" aria-live="polite"></p>
    `;

    this.input = root.querySelector('.gbx-rom-loader__input') as HTMLInputElement;
    this.status = root.querySelector('.gbx-rom-loader__status') as HTMLParagraphElement;

    document.body.appendChild(root);
  }

  private initSignals(): void {
    this.root.addEventListener('click', (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      if (target.closest('[data-rom-action="pick"]')) {
        this.input.click();
      }
    });

    this.input.addEventListener('change', () => {
      const file = this.input.files && this.input.files[0];
      this.input.value = '';
      if (file) {
        this.handleFile(file);
      }
    });

    window.addEventListener('dragover', (event: DragEvent) => {
      event.preventDefault();
    });

    window.addEventListener('drop', (event: DragEvent) => {
      event.preventDefault();
      const file = event.dataTransfer && event.dataTransfer.files && event.dataTransfer.files[0];
      if (file) {
        this.handleFile(file);
      }
    });
  }

  private handleFile(file: File): void {
    const copy = COPY[readLanguage()];
    const lowerName = file.name.toLowerCase();

    if (!lowerName.endsWith('.gb') && !lowerName.endsWith('.gbc')) {
      this.showStatus(copy.invalid);
      return;
    }
    if (file.size > MAX_ROM_BYTES) {
      this.showStatus(copy.tooLarge);
      return;
    }
    if (file.size < MIN_ROM_BYTES) {
      this.showStatus(copy.tooSmall);
      return;
    }

    this.clearStatus();
    this.events.emit('onUserRomSelected', {
      file,
      title: this.romTitle(file.name),
    } satisfies UserRomSource);
  }

  private romTitle(fileName: string): string {
    const base = fileName.replace(/\.(gb|gbc)$/i, '').replace(/[_-]+/g, ' ').trim();
    const title = base === '' ? 'USER ROM' : base;
    return title.slice(0, MAX_TITLE_CHARS).toUpperCase();
  }

  private showStatus(message: string): void {
    this.status.textContent = message;
    if (this.statusTimer !== null) {
      window.clearTimeout(this.statusTimer);
    }
    this.statusTimer = window.setTimeout(() => this.clearStatus(), 4200);
  }

  private clearStatus(): void {
    if (this.statusTimer !== null) {
      window.clearTimeout(this.statusTimer);
      this.statusTimer = null;
    }
    this.status.textContent = '';
  }
}
