import { EventEmitter } from 'pixi.js';
import DEBUG_CONFIG from '../Data/Configs/Main/debug-config';
import { GAME_BOY_COLORS, DEFAULT_GAME_BOY_COLOR, GameBoyColor, GameBoyColorId } from './game-boy-colors';

const COLOR_PICKER_STORAGE_KEY = 'gamex:game-boy-color-picker-collapsed';

function readCollapsedPreference(): boolean {
  try {
    return window.localStorage.getItem(COLOR_PICKER_STORAGE_KEY) === 'true';
  } catch {
    return false;
  }
}

function writeCollapsedPreference(collapsed: boolean): void {
  try {
    window.localStorage.setItem(COLOR_PICKER_STORAGE_KEY, String(collapsed));
  } catch {
    // Keep the current in-memory view when storage is unavailable.
  }
}

// A self-contained DOM overlay (no framework) mirroring the CartridgeInfoPanel
// pattern: builds its own markup, reads shared styles from style.css. Compact
// Tamagotchi-style 2x4 swatch grid; each swatch also answers to its printed
// 1-8 shortcut so the picker works without pointing at it.
export default class GameBoyColorPicker {
  public events: EventEmitter;
  private root: HTMLDivElement;
  private activeColorId: GameBoyColorId = DEFAULT_GAME_BOY_COLOR;
  private collapsed = readCollapsedPreference();

  constructor() {
    this.events = new EventEmitter();

    this.build();
    this.initSignals();
  }

  private build(): void {
    const root = this.root = document.createElement('div');
    root.className = 'gbx-color-picker';
    root.hidden = DEBUG_CONFIG.withoutUIMode;

    root.innerHTML = `
      <section class="gbx-color-picker__panel" aria-label="GX Pocket colors">
        <div class="gbx-color-picker__header">
          <span class="gbx-color-picker__kicker">GX POCKET</span>
          <strong>COLOR</strong>
          <button
            class="gbx-color-picker__collapse"
            type="button"
            data-picker-action="collapse"
            aria-label="Hide color picker"
            aria-expanded="true"
          ><span aria-hidden="true">&minus;</span></button>
        </div>
        <div class="gbx-color-picker__swatches">
          ${GAME_BOY_COLORS.map((color: GameBoyColor) => this.swatchMarkup(color)).join('')}
        </div>
      </section>
      <button
        class="gbx-color-picker__handle"
        type="button"
        data-picker-action="expand"
        aria-label="Show color picker"
        aria-expanded="false"
      ><span class="gbx-color-picker__ring" aria-hidden="true"></span></button>
    `;

    this.updateActiveSwatch();
    this.setCollapsed(this.collapsed, false);
    document.body.appendChild(root);
  }

  private swatchMarkup(color: GameBoyColor): string {
    const isActive = color.id === this.activeColorId;
    return `
      <button
        type="button"
        class="gbx-color-swatch${isActive ? ' is-active' : ''}"
        data-color-id="${color.id}"
        data-shortcut="${color.shortcut}"
        title="${color.name} (${color.shortcut})"
        aria-label="${color.name}"
        aria-pressed="${isActive}"
      >
        <span style="--swatch: ${color.swatch};"></span>
        <i class="gbx-color-swatch__shortcut">${color.shortcut}</i>
      </button>
    `;
  }

  private initSignals(): void {
    this.root.addEventListener('click', (event: MouseEvent) => {
      const target = event.target as HTMLElement;
      const actionButton = target.closest('[data-picker-action]') as HTMLButtonElement | null;

      if (actionButton) {
        const action = actionButton.dataset.pickerAction;
        if (action === 'collapse') {
          this.setCollapsed(true, true);
        } else if (action === 'expand') {
          this.setCollapsed(false, true);
        }
        return;
      }

      const swatchButton = target.closest('.gbx-color-swatch') as HTMLButtonElement | null;
      if (!swatchButton) {
        return;
      }

      this.selectColor(swatchButton.dataset.colorId as GameBoyColorId);
    });

    this.root.addEventListener('keydown', (event: KeyboardEvent) => {
      if (event.key !== 'Escape') {
        return;
      }

      event.preventDefault();
      event.stopPropagation();

      if (!this.collapsed) {
        this.setCollapsed(true, true);
      }
    });

    window.addEventListener('keydown', (event: KeyboardEvent) => {
      if (event.repeat) {
        return;
      }

      const target = event.target as HTMLElement | null;
      if (target && (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable)) {
        return;
      }

      const color = GAME_BOY_COLORS.find((entry: GameBoyColor) => entry.shortcut === event.key);
      if (color) {
        this.selectColor(color.id);
      }
    });
  }

  private selectColor(colorId: GameBoyColorId): void {
    if (!colorId || colorId === this.activeColorId) {
      return;
    }

    this.activeColorId = colorId;
    this.updateActiveSwatch();
    this.events.emit('onColorChanged', colorId);
  }

  private setCollapsed(collapsed: boolean, restoreFocus: boolean): void {
    this.collapsed = collapsed;
    this.root.classList.toggle('is-collapsed', collapsed);

    const panel = this.root.querySelector('.gbx-color-picker__panel') as HTMLElement;
    const handle = this.root.querySelector('.gbx-color-picker__handle') as HTMLButtonElement;
    const collapseButton = this.root.querySelector('.gbx-color-picker__collapse') as HTMLButtonElement;
    const expanded = String(!collapsed);

    panel.hidden = collapsed;
    panel.setAttribute('aria-hidden', String(collapsed));
    handle.hidden = !collapsed;
    handle.setAttribute('aria-hidden', String(!collapsed));
    handle.setAttribute('aria-expanded', expanded);
    collapseButton.setAttribute('aria-expanded', expanded);
    handle.tabIndex = collapsed ? 0 : -1;
    collapseButton.tabIndex = collapsed ? -1 : 0;
    this.root.querySelectorAll<HTMLButtonElement>('.gbx-color-swatch').forEach((button) => {
      button.tabIndex = collapsed ? -1 : 0;
    });

    writeCollapsedPreference(collapsed);

    if (restoreFocus) {
      (collapsed ? handle : collapseButton).focus();
    }
  }

  private updateActiveSwatch(): void {
    this.root.querySelectorAll<HTMLButtonElement>('.gbx-color-swatch').forEach((button) => {
      const isActive = button.dataset.colorId === this.activeColorId;
      button.classList.toggle('is-active', isActive);
      button.setAttribute('aria-pressed', String(isActive));
    });

    const activeColor = GAME_BOY_COLORS.find((color: GameBoyColor) => color.id === this.activeColorId);
    if (activeColor) {
      this.root.style.setProperty('--gbx-active-color', activeColor.swatch);
    }
  }
}
