import * as THREE from 'three';
import TWEEN from 'three/addons/libs/tween.module.js';
import Cartridge from './cartridge';
import { CARTRIDGES_CONFIG, CARTRIDGE_TYPE } from './data/cartridges-config';
import { EventEmitter } from 'pixi.js';
import { GAME_BOY_CONFIG } from '../game-boy/data/game-boy-config';
import { Timeout } from '../../../core/helpers/timeout';

const CAROUSEL_DRAG_SPEED = 0.009;
const DETAIL_DRAG_SPEED = 0.012;
const DETAIL_POSITION = new THREE.Vector3(0, 0.65, 3.15);
const DETAIL_SCALE = 1.12;
const WORLD_X_AXIS = new THREE.Vector3(1, 0, 0);
const WORLD_Y_AXIS = new THREE.Vector3(0, 1, 0);

type DetailInteractionState = 'idle' | 'entering' | 'active' | 'returning';

interface StoppableTween {
  stop(): void;
}

export default class CartridgesController extends THREE.Group {
  public events: EventEmitter;

  private cartridges: { [key in CARTRIDGE_TYPE]?: Cartridge };
  private cartridgesArray: Cartridge[];
  private carouselGroup: THREE.Group;
  private carouselDragStartQuaternion: THREE.Quaternion;
  private detailDragStartQuaternion: THREE.Quaternion;
  private detailCartridge: Cartridge | null;
  private detailOriginalPosition: THREE.Vector3;
  private detailOriginalQuaternion: THREE.Quaternion;
  private detailOriginalScale: THREE.Vector3;
  private detailTweens: StoppableTween[];
  private detailState: DetailInteractionState;
  private detailEntryDragOffset: THREE.Vector2;

  private timeByCartridgeType: { [key in CARTRIDGE_TYPE]?: number };
  private showCartridgeObjects: { [key in CARTRIDGE_TYPE]?: THREE.Object3D };
  private showCartridgeTween: { [key in CARTRIDGE_TYPE]?: any };
  private isCartridgeShown: { [key in CARTRIDGE_TYPE]?: boolean };
  private positionObject: { [key in CARTRIDGE_TYPE]?: THREE.Object3D };
  private cartridgeDisableFloating: { [key in CARTRIDGE_TYPE]?: boolean };
  private insertedCartridge: Cartridge;

  private isInsertingActive: boolean;
  private isEjectingActive: boolean;

  constructor() {
    super();

    this.events = new EventEmitter();

    this.cartridges = {};
    this.cartridgesArray = [];
    this.carouselGroup = new THREE.Group();
    this.carouselGroup.name = 'cartridge-carousel';
    this.add(this.carouselGroup);
    this.carouselDragStartQuaternion = new THREE.Quaternion();
    this.detailDragStartQuaternion = new THREE.Quaternion();
    this.detailCartridge = null;
    this.detailOriginalPosition = new THREE.Vector3();
    this.detailOriginalQuaternion = new THREE.Quaternion();
    this.detailOriginalScale = new THREE.Vector3();
    this.detailTweens = [];
    this.detailState = 'idle';
    this.detailEntryDragOffset = new THREE.Vector2();

    this.timeByCartridgeType = {};
    this.showCartridgeObjects = {};
    this.showCartridgeTween = {};
    this.isCartridgeShown = {};
    this.positionObject = {};
    this.cartridgeDisableFloating = {};
    this.insertedCartridge = null;

    this.isInsertingActive = false;
    this.isEjectingActive = false;

    this.init();
  }

  public update(dt: number) {
    this.cartridgesArray.forEach(cartridge => {
      const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();

      if (!this.cartridgeDisableFloating[cartridgeType]) {
        const floatingConfig = CARTRIDGES_CONFIG.floating[cartridgeType];
        this.timeByCartridgeType[cartridgeType] += dt;

        cartridge.rotation.z = Math.sin(this.timeByCartridgeType[cartridgeType] * floatingConfig.speed * 0.5) * floatingConfig.rotation.z * THREE.MathUtils.DEG2RAD;

        this.positionObject[cartridgeType].position.y = cartridge.startPosition.y + Math.sin(this.timeByCartridgeType[cartridgeType] * floatingConfig.speed) * floatingConfig.amplitude;
        cartridge.position.lerp(this.positionObject[cartridgeType].position, 0.1);
      }
    });
  }

  public getAllMeshes(): THREE.Mesh[] {
    const allMeshes: THREE.Mesh[] = [];

    this.cartridgesArray.forEach(cartridge => {
      allMeshes.push(cartridge.getMesh());
    });

    return allMeshes;
  }

  public onPointerDragDown(cartridgeObject: THREE.Object3D): void {
    if (this.detailState === 'entering') {
      this.detailEntryDragOffset.set(0, 0);
      return;
    }

    if (this.detailState === 'returning') {
      return;
    }

    if (this.isDetailCartridgeObject(cartridgeObject)) {
      this.detailEntryDragOffset.set(0, 0);
      this.detailDragStartQuaternion.copy(this.detailCartridge.quaternion);
      return;
    }

    this.carouselDragStartQuaternion.copy(this.carouselGroup.quaternion);
  }

  public onPointerDragMove(deltaX: number, deltaY: number): void {
    if (this.detailState === 'entering') {
      this.detailEntryDragOffset.set(deltaX, deltaY);
      return;
    }

    if (this.detailState === 'returning') {
      return;
    }

    if (this.detailCartridge) {
      const detailDeltaX = deltaX - this.detailEntryDragOffset.x;
      const detailDeltaY = deltaY - this.detailEntryDragOffset.y;
      this.detailCartridge.quaternion.copy(this.detailDragStartQuaternion);
      this.detailCartridge.rotateOnWorldAxis(WORLD_Y_AXIS, -detailDeltaX * DETAIL_DRAG_SPEED);
      this.detailCartridge.rotateOnWorldAxis(WORLD_X_AXIS, -detailDeltaY * DETAIL_DRAG_SPEED);
      return;
    }

    this.carouselGroup.quaternion.copy(this.carouselDragStartQuaternion);
    this.carouselGroup.rotateOnWorldAxis(WORLD_Y_AXIS, -deltaX * CAROUSEL_DRAG_SPEED);
    this.carouselGroup.rotateOnWorldAxis(WORLD_X_AXIS, -deltaY * CAROUSEL_DRAG_SPEED);
  }

  public onDragPointerUp(): void {
    this.detailEntryDragOffset.set(0, 0);
  }

  public beginCartridgeDetail(cartridgeObject: THREE.Object3D): boolean {
    if (this.detailState !== 'idle' || this.detailCartridge || this.isInsertingActive || this.isEjectingActive) {
      return false;
    }

    const cartridgeType = cartridgeObject.userData['partType'] as CARTRIDGE_TYPE;
    const cartridge = this.cartridges[cartridgeType];
    if (!cartridge || cartridge.isInserted()) {
      return false;
    }

    this.stopDetailTweens();
    this.disableCartridges();
    cartridge.enableActivity();
    this.cartridgeDisableFloating[cartridgeType] = true;

    this.detailOriginalPosition.copy(cartridge.position);
    this.detailOriginalQuaternion.copy(cartridge.quaternion);
    this.detailOriginalScale.copy(cartridge.scale);
    this.attach(cartridge);
    this.detailCartridge = cartridge;
    this.detailState = 'entering';
    this.detailEntryDragOffset.set(0, 0);
    this.detailDragStartQuaternion.copy(cartridge.quaternion);

    let remainingEntryTweens = 3;
    const finalizeDetailEntry = (): void => {
      remainingEntryTweens -= 1;
      if (remainingEntryTweens > 0 || this.detailState !== 'entering') {
        return;
      }

      cartridge.position.copy(DETAIL_POSITION);
      cartridge.quaternion.identity();
      cartridge.scale.setScalar(DETAIL_SCALE);
      this.detailDragStartQuaternion.copy(cartridge.quaternion);
      this.detailState = 'active';
      this.detailTweens = [];
    };

    const positionTween = new TWEEN.Tween(cartridge.position)
      .to({ x: DETAIL_POSITION.x, y: DETAIL_POSITION.y, z: DETAIL_POSITION.z }, 360)
      .easing(TWEEN.Easing.Cubic.Out)
      .onComplete(finalizeDetailEntry)
      .start();
    const scaleTween = new TWEEN.Tween(cartridge.scale)
      .to({ x: DETAIL_SCALE, y: DETAIL_SCALE, z: DETAIL_SCALE }, 360)
      .easing(TWEEN.Easing.Cubic.Out)
      .onComplete(finalizeDetailEntry)
      .start();
    const rotationTween = new TWEEN.Tween(cartridge.quaternion)
      .to({ x: 0, y: 0, z: 0, w: 1 }, 360)
      .easing(TWEEN.Easing.Cubic.Out)
      .onUpdate(() => cartridge.quaternion.normalize())
      .onComplete(finalizeDetailEntry)
      .start();

    this.detailTweens = [positionTween, scaleTween, rotationTween];
    this.events.emit('detailModeChanged', cartridgeType);
    return true;
  }

  public exitCartridgeDetail(): boolean {
    if (!this.detailCartridge || this.detailState === 'idle' || this.detailState === 'returning') {
      return false;
    }

    const cartridge = this.detailCartridge;
    const cartridgeType = cartridge.getType();
    this.detailState = 'returning';
    this.stopDetailTweens();
    this.carouselGroup.attach(cartridge);

    let remainingReturnTweens = 3;
    const finalizeDetailReturn = (): void => {
      remainingReturnTweens -= 1;
      if (remainingReturnTweens > 0) {
        return;
      }

      cartridge.position.copy(this.detailOriginalPosition);
      cartridge.quaternion.copy(this.detailOriginalQuaternion);
      cartridge.scale.copy(this.detailOriginalScale);
      this.detailCartridge = null;
      this.detailState = 'idle';
      this.detailTweens = [];
      this.cartridgeDisableFloating[cartridgeType] = false;
      this.enableCartridges();
      this.events.emit('detailModeChanged', null);
    };

    const positionTween = new TWEEN.Tween(cartridge.position)
      .to({
        x: this.detailOriginalPosition.x,
        y: this.detailOriginalPosition.y,
        z: this.detailOriginalPosition.z,
      }, 320)
      .easing(TWEEN.Easing.Cubic.Out)
      .onComplete(finalizeDetailReturn)
      .start();
    const scaleTween = new TWEEN.Tween(cartridge.scale)
      .to({
        x: this.detailOriginalScale.x,
        y: this.detailOriginalScale.y,
        z: this.detailOriginalScale.z,
      }, 320)
      .easing(TWEEN.Easing.Cubic.Out)
      .onComplete(finalizeDetailReturn)
      .start();
    const rotationTween = new TWEEN.Tween(cartridge.quaternion)
      .to({
        x: this.detailOriginalQuaternion.x,
        y: this.detailOriginalQuaternion.y,
        z: this.detailOriginalQuaternion.z,
        w: this.detailOriginalQuaternion.w,
      }, 320)
      .easing(TWEEN.Easing.Cubic.Out)
      .onUpdate(() => cartridge.quaternion.normalize())
      .onComplete(finalizeDetailReturn)
      .start();

    this.detailTweens = [positionTween, scaleTween, rotationTween];
    return true;
  }

  public isDetailModeActive(): boolean {
    return this.detailState !== 'idle';
  }

  public isDetailCartridgeObject(object: THREE.Object3D): boolean {
    return this.detailCartridge?.getMesh() === object;
  }

  public getInteractionState() {
    const carouselRotation = new THREE.Euler().setFromQuaternion(this.carouselGroup.quaternion, 'XYZ');
    return {
      galleryCartridges: this.cartridgesArray
        .filter((cartridge) => CARTRIDGES_CONFIG.floating[cartridge.getType()].startPosition.y < 6)
        .map((cartridge) => cartridge.getType()),
      insertedCartridge: this.insertedCartridge?.getType() ?? null,
      detailCartridge: this.detailCartridge?.getType() ?? null,
      carouselRotation: {
        x: Number(carouselRotation.x.toFixed(4)),
        y: Number(carouselRotation.y.toFixed(4)),
      },
    };
  }

  public onPointerDown(mesh: THREE.Mesh) {
    if (this.detailState !== 'idle' || this.detailCartridge) {
      return;
    }

    this.disableCartridges();

    const cartridgeType: CARTRIDGE_TYPE = mesh.userData['partType'];
    const cartridge: Cartridge = this.cartridges[cartridgeType];

    const insertedCartridge: Cartridge = this.checkIsCartridgeInserted(cartridge);

    if (insertedCartridge !== null) {
      this.events.emit('onCartridgeEjecting');
      this.moveCartridgeFromGameBoy(insertedCartridge, 7, 200);

      this.events.emit('onCartridgeInserting');
      this.moveCartridgeToGameBoy(cartridge, 3.2);
    } else {

      if (!cartridge.isInserted()) {
        this.events.emit('onCartridgeInserting');
        this.moveCartridgeToGameBoy(cartridge, 5);
      } else {
        this.events.emit('onCartridgeEjecting');
        this.moveCartridgeFromGameBoy(cartridge, 5, 400);
      }
    }
  }

  public onZoomChanged(zoomPercent: number) {
    this.cartridgesArray.forEach(cartridge => {
      const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();
      const sideDirection = Math.sign(cartridge.startPosition.x);
      this.positionObject[cartridgeType].position.x = cartridge.startPosition.x + sideDirection * 1.8 * zoomPercent;
    });
  }

  public ejectCartridge() {
    if (this.insertedCartridge) {
      const mesh: THREE.Mesh = this.insertedCartridge.getMesh();
      this.onPointerDown(mesh);
    }
  }

  public insertCartridge(cartridgeType: CARTRIDGE_TYPE) {
    if (this.insertedCartridge) {
      const insertedCartridgeType: CARTRIDGE_TYPE = this.insertedCartridge.getType();

      if (insertedCartridgeType !== cartridgeType) {
        const mesh: THREE.Mesh = this.cartridges[cartridgeType].getMesh();
        this.onPointerDown(mesh);
      }
    } else {
      const mesh: THREE.Mesh = this.cartridges[cartridgeType].getMesh();
      this.onPointerDown(mesh);
    }
  }

  public onPointerOver(): void { }

  public onPointerOut(): void { }

  public getOutlineMeshes(object: THREE.Object3D): THREE.Object3D[] {
    return [object];
  }

  public stopTween(cartridgeType: CARTRIDGE_TYPE): void {
    if (this.showCartridgeTween[cartridgeType]) {
      this.showCartridgeTween[cartridgeType].stop();
    }
  }

  private checkIsCartridgeInserted(clickedCartridge: Cartridge): Cartridge | null {
    let isCartridgeInserted: Cartridge | null = null;

    this.cartridgesArray.forEach(cartridge => {
      if (cartridge.isInserted() && cartridge.getType() !== clickedCartridge.getType()) {
        isCartridgeInserted = cartridge;
      }
    });

    return isCartridgeInserted;
  }

  private moveCartridgeToGameBoy(cartridge: Cartridge, speed: number): void {
    const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();
    const galleryRotation = cartridge.rotation.clone();
    this.attach(cartridge);
    cartridge.setInserted();

    this.insertedCartridge = cartridge;
    this.isInsertingActive = true;

    this.cartridgeDisableFloating[cartridgeType] = true;
    cartridge.lastRotation.copy(galleryRotation);

    const positions = CARTRIDGES_CONFIG.positions.insert;
    const distance = cartridge.position.distanceTo(positions.beforeInsert);
    const time = distance / (speed * 0.001);

    new TWEEN.Tween(cartridge.scale)
      .to({ x: 1, y: 1, z: 1 }, time)
      .easing(TWEEN.Easing.Sinusoidal.Out)
      .start();

    new TWEEN.Tween(cartridge.position)
      .to({
        x: [positions.middle.x, positions.beforeInsert.x],
        y: [positions.middle.y, positions.beforeInsert.y],
        z: [positions.middle.z, positions.beforeInsert.z],
        }, time)
      .interpolation(TWEEN.Interpolation.Bezier)
      .easing(TWEEN.Easing.Sinusoidal.Out)
      .start()
      .onComplete(() => {
        new TWEEN.Tween(cartridge.position)
          .to({ x: positions.slot.x, y: positions.slot.y, z: positions.slot.z }, 400)
          .easing(TWEEN.Easing.Back.In)
          .delay(100)
          .start()
          .onComplete(() => {
            this.onCartridgeInserted(cartridge);
          });

        Timeout.call(200, () => this.events.emit('cartridgeInsertSound'));
      });

    new TWEEN.Tween(cartridge.rotation)
      .to({ x: 0, y: Math.PI, z: 0 }, time)
      .easing(TWEEN.Easing.Quartic.Out)
      .start();
  }

  private moveCartridgeFromGameBoy(cartridge: Cartridge, speed: number, ejectTime: number): void {
    const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();
    cartridge.setNotInserted();

    this.isEjectingActive = true;
    GAME_BOY_CONFIG.currentCartridge = 'NONE';
    this.insertedCartridge = null;
    this.events.emit('cartridgeTypeChanged');
    this.events.emit('cartridgeEjectSound');
    this.events.emit('cartridgeStartEjecting');

    const positions = CARTRIDGES_CONFIG.positions.eject;
    const floatingConfig = CARTRIDGES_CONFIG.floating[cartridgeType];

    cartridge.setStandardTexture();

    const moveTween = new TWEEN.Tween(cartridge.position)
      .to({ x: positions.beforeEject.x, y: positions.beforeEject.y, z: positions.beforeEject.z }, ejectTime)
      .easing(TWEEN.Easing.Sinusoidal.Out)
      .delay(400)
      .start()
      .onComplete(() => {
        this.carouselGroup.attach(cartridge);
        const distance = cartridge.position.distanceTo(floatingConfig.startPosition);
        const time = distance / (speed * 0.001);

        new TWEEN.Tween(cartridge.scale)
          .to({
            x: CARTRIDGES_CONFIG.floatingScale,
            y: CARTRIDGES_CONFIG.floatingScale,
            z: CARTRIDGES_CONFIG.floatingScale,
          }, time)
          .easing(TWEEN.Easing.Sinusoidal.Out)
          .start();

        new TWEEN.Tween(cartridge.position)
          .to({
            x: [positions.middle.x, floatingConfig.startPosition.x],
            y: [positions.middle.y, floatingConfig.startPosition.y],
            z: [positions.middle.z, floatingConfig.startPosition.z],
            }, time)
          .interpolation(TWEEN.Interpolation.Bezier)
          .easing(TWEEN.Easing.Sinusoidal.Out)
          .start()
          .onComplete(() => {
            cartridge.position.copy(floatingConfig.startPosition);
            this._onCartridgeEjected(cartridgeType);
          });

        new TWEEN.Tween(cartridge.rotation)
          .to({
            x: cartridge.lastRotation.x,
            y: cartridge.lastRotation.y,
            z: cartridge.lastRotation.z,
          }, time)
          .easing(TWEEN.Easing.Quartic.Out)
          .start();
      });

    moveTween.onStart(() => {
      this.attach(cartridge);
    });
  }

  private onCartridgeInserted(cartridge: Cartridge): void {
    this.isInsertingActive = false;
    const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();
    GAME_BOY_CONFIG.currentCartridge = cartridgeType;
    this.events.emit('cartridgeTypeChanged');
    this.events.emit('onCartridgeInserted', cartridge);
    cartridge.setInPocketTexture();

    this.enableCartridges();
  }

  private _onCartridgeEjected(cartridgeType: CARTRIDGE_TYPE): void {
    this.isEjectingActive = false;
    this.cartridgeDisableFloating[cartridgeType] = false;
    this.enableCartridges();
    this.events.emit('onCartridgeEjected');
  }

  private disableCartridges(): void {
    this.cartridgesArray.forEach(cartridge => {
      cartridge.disableActivity();
    });
  }

  private enableCartridges(): void {
    if (this.isInsertingActive || this.isEjectingActive) {
      return;
    }

    this.cartridgesArray.forEach((cartridge: Cartridge) => {
      cartridge.enableActivity();
    });
  }

  private stopDetailTweens(): void {
    this.detailTweens.forEach((tween) => tween.stop());
    this.detailTweens = [];
  }

  private init(): void {
    this.initCartridges();
    this.initShowCartridgeObjects();
  }

  private initCartridges(): void {
    const cartridgesTypes: CARTRIDGE_TYPE[] = [
      CARTRIDGE_TYPE.Adjustris,
      CARTRIDGE_TYPE.BrekstasCat,
      CARTRIDGE_TYPE.Airplanz,
      CARTRIDGE_TYPE.CrossConnect,
      CARTRIDGE_TYPE.DysonsFear,
      CARTRIDGE_TYPE.UnstoppableKnight,
      CARTRIDGE_TYPE.Wyrmhole,
      CARTRIDGE_TYPE.TobuTobuGirl,
      CARTRIDGE_TYPE.MicroCity,
      CARTRIDGE_TYPE.Game2048,
      CARTRIDGE_TYPE.GbCorp,
      CARTRIDGE_TYPE.Carazu,
      CARTRIDGE_TYPE.ShockLobster,
      CARTRIDGE_TYPE.Geometrix,
      CARTRIDGE_TYPE.GbWordyl,
    ];

    for (let i = 0; i < cartridgesTypes.length; i++) {
      const type: CARTRIDGE_TYPE = cartridgesTypes[i];
      const config = CARTRIDGES_CONFIG.floating[type];

      const cartridge: Cartridge = new Cartridge(type);
      this.carouselGroup.add(cartridge);

      cartridge.position.copy(config.startPosition);
      cartridge.startPosition = cartridge.position.clone();
      cartridge.scale.setScalar(CARTRIDGES_CONFIG.floatingScale);

      cartridge.rotation.y = config.rotation.y * THREE.MathUtils.DEG2RAD;
      cartridge.rotation.x = config.rotation.x * THREE.MathUtils.DEG2RAD;

      this.cartridges[type] = cartridge;
      this.cartridgesArray.push(cartridge);
    }
  }

  private initShowCartridgeObjects(): void {
    this.cartridgesArray.forEach((cartridge: Cartridge) => {
      const cartridgeType: CARTRIDGE_TYPE = cartridge.getType();
      this.showCartridgeObjects[cartridgeType] = new THREE.Object3D();
      this.isCartridgeShown[cartridgeType] = false;
      this.cartridgeDisableFloating[cartridgeType] = false;
      this.timeByCartridgeType[cartridgeType] = 0;
      this.positionObject[cartridgeType] = new THREE.Object3D();
      this.positionObject[cartridgeType].position.copy(cartridge.position);
    });
  }
}
