import { Container, EventEmitter, Application } from "pixi.js";
import Overlay from "./overlay";
import SoundIcon from './sound-icon';
import GameBoyColorPicker from './game-boy-color-picker';
import GameBoyRomLoader from './game-boy-rom-loader';
import { GameBoyColorId } from './game-boy-colors';
import type { UserRomSource } from '../scene/game-boy-scene/game-boy-games/games/emulator/user-rom-source';

export default class UI extends Container {
  public events: EventEmitter;

  private pixiApp: Application;
  private overlay: Overlay;
  private soundIcon: SoundIcon;
  private colorPicker: GameBoyColorPicker;
  private romLoader: GameBoyRomLoader;

  constructor(pixiApp: Application) {
    super();

    this.events = new EventEmitter();

    this.pixiApp = pixiApp;

    this.init();
  }

  public onResize(): void {
    const width = window.innerWidth;
    const height = window.innerHeight;

    this.soundIcon.x = 50;
    this.soundIcon.y = 50;

    this.overlay.onResize(width, height);
  }

  public updateSoundIcon(): void {
    this.soundIcon.updateTexture();
  }

  private init(): void {
    this.initOverlay();
    this.initSoundIcon();
    this.initColorPicker();
    this.initRomLoader();
    this.initSignals();

    this.onResize();
  }

  private initOverlay(): void {
    const overlay = this.overlay = new Overlay();
    this.addChild(overlay);
  }

  private initSoundIcon(): void {
    const soundIcon = this.soundIcon = new SoundIcon();
    this.addChild(soundIcon);
  }

  private initColorPicker(): void {
    this.colorPicker = new GameBoyColorPicker();
  }

  private initRomLoader(): void {
    this.romLoader = new GameBoyRomLoader();
  }

  private initSignals(): void {
    this.overlay.events.on('onPointerMove', (x: number, y: number) => this.events.emit('onPointerMove', x, y));
    this.overlay.events.on('onPointerDown', (x: number, y: number) => this.events.emit('onPointerDown', x, y));
    this.overlay.events.on('onPointerUp', (x: number, y: number) => this.events.emit('onPointerUp', x, y));
    this.overlay.events.on('onPointerCancel', () => this.events.emit('onPointerCancel'));
    this.pixiApp.canvas.addEventListener('pointerleave', () => this.events.emit('onPointerCancel'));
    this.pixiApp.canvas.addEventListener('wheel', (event: WheelEvent) => this.events.emit('onWheelScroll', Math.sign(event.deltaY)));
    window.addEventListener('blur', () => this.events.emit('onPointerCancel'));

    this.soundIcon.events.on('onSoundChanged', () => this.events.emit('onSoundChanged'));
    this.colorPicker.events.on('onColorChanged', (colorId: GameBoyColorId) => this.events.emit('onColorChanged', colorId));
    this.romLoader.events.on('onUserRomSelected', (source: UserRomSource) => this.events.emit('onUserRomSelected', source));
  }
}
