// A user-provided ROM (picked from their own device) staged for the emulator.
// The app never ships or fetches commercial ROMs — this only holds a File the
// user chose locally, for e.g. playing a personal backup of a cartridge they
// own. It never persists to disk or leaves the browser.

export const USER_ROM_CARTRIDGE_ID = 'USER_ROM';

export interface UserRomSource {
  file: File;
  title: string;
}

let currentSource: UserRomSource | null = null;

export function setUserRomSource(source: UserRomSource): void {
  currentSource = source;
}

export function getUserRomSource(): UserRomSource | null {
  return currentSource;
}
